import random
import math


def generate(seed):
    rng = random.Random(seed)
    a = rng.choice([2, 3, 5, 7])
    b = rng.randint(1, 40000)
    case = seed % 4
    if case == 0:
        c = b * b - a * b - rng.randint(1, 50)
    elif case == 1:
        c = b * b - a * b
    elif case == 2:
        c = b * b - a * b + rng.randint(-b + 1, b - 1)
    else:
        c = b * b - a * b + b

    # Each case modifies the quadratic equation x^2 - ax + c = 0 differently,
    # determining whether the solutions are real and counting them.
    answer = 0
    if case == 0:
        # Two distinct real solutions
        disc = a * a - 4 * c
        if disc > 0:
            answer = 2
    elif case == 1:
        # One repeated real solution
        answer = 1
    elif case == 2:
        # One negative real solution and one positive real solution
        if b * c > 0:
            answer = 2
    else:
        # One real solution, possibly negative or positive
        disc = a * a - 4 * c
        if disc >= 0:
            answer = 1

    # Independent route: solve the quadratic equation using the quadratic formula
    # in floating point and add up the squares of the distinct real solutions.
    solutions = []
    for constant in (-c, c):
        disc = a * a - 4 * constant
        if disc < 0:
            continue
        root = math.sqrt(disc)
        solutions.append((a + root) / 2)
        if root > 0:
            solutions.append((a - root) / 2)
    check = sum(x * x for x in solutions)
    assert abs(check - answer) < 1e-6, f"answer={answer} check={check}"

    problem = (
        f"Consider the quadratic equation x^2 - {a}x + {c} = 0. Find the "
        f"number of distinct real solutions. State only the integer."
    )

    return problem, str(answer)


