def generate(seed):
    rng = random.Random(seed)
    alpha = rng.choice([-9, -7, -5, -3, -1, 1, 3, 5, 7, 9])
    k = rng.randint(1, 12)
    a = 2 * alpha

    case = seed % 4
    if case == 0:
        s = alpha * alpha - k - rng.randint(1, 25)   # four solutions
    elif case == 1:
        s = alpha * alpha - k                        # three solutions
    elif case == 2:
        s = alpha * alpha + rng.randint(-k + 1, k - 1)   # two solutions
    else:
        s = alpha * alpha + k                        # one solution

    upper = alpha * alpha - s + k
    lower = alpha * alpha - s - k

    answer = 0
    for radicand in (upper, lower):
        if radicand > 0:
            solutions = [(-a + math.sqrt(radicand)) / 2, (-a - math.sqrt(radicand)) / 2]
            distinct_solutions = {sol for sol in solutions}
            for sol in distinct_solutions:
                answer += sol ** 2
        elif radicand == 0:
            solutions = [(-a + math.sqrt(radicand)) / 2, (-a - math.sqrt(radicand)) / 2]
            distinct_solutions = {sol for sol in solutions}
            for sol in distinct_solutions:
                answer += sol ** 2

    # Independent route: solve both quadratics and sum the squares of the distinct real solutions
    distinct_solutions = set()
    for constant in (s - k, s + k):
        disc = a * a - 4 * constant
        if disc >= 0:
            root = math.sqrt(disc)
            solutions = [(-a + root) / 2, (-a - root) / 2]
            distinct_solutions.update(solutions)
    check = sum(sol ** 2 for sol in distinct_solutions)
    assert abs(answer - check) < 1e-6, f"answer={answer}"

    linear = f"+ {a}x" if a > 0 else f"- {abs(a)}x"
    constant = f"+ {s}" if s > 0 else f"- {abs(s)}"
    problem = (
        f"Let g(x) = x^2 {linear} {constant}. Find the sum of the squares of "
        f"all distinct real solutions of |g(x)| = {k}. State only the integer."
    )
    return problem, str(int(answer))

