    def is_on_diagonals(segment, diagonal1, diagonal2):
        (x1, y1), (x2, y2) = segment
        (dx1, dy1), (dx2, dy2) = diagonal1, diagonal2
        return (dx1 * (y2 - y1) - dy1 * (x2 - x1)) == (dx2 * (y1 - y2) - dy2 * (x1 - x2)) == 0

    diagonals = sorted([(vertices[i], vertices[j]) for i in range(num_vertices) for j in range(i + 1, num_vertices) if i != 0 or j != num_vertices - 1])

    count_both_diagonals = 0
