            for segment in [(vertices[i], vertices[(i + 1) % num_vertices]) for i in range(num_vertices)]:
                if is_on_diagonals(segment, diagonal1, diagonal2):
                    count += 1
            if count == num_vertices:
                count_both_diagonals += 1

    answer = count_both_diagonals

    # Independent route: count the number of diagonals that intersect the polygon's vertices in a specific way.
