def _prime_factors(n):
    factors = set()
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.add(d)
            n //= d
        d += 1
    if n > 1:
        factors.add(n)
    return factors


def _primitive_root(p):
    factors = sorted(_prime_factors(p - 1))  # sorted(): determinism rule
    for g in range(2, p):
        if all(pow(g, (p - 1) // q, p) != 1 for q in factors):
            return g
    return 2


def _is_primitive_root(g, p):
    factors = sorted(_prime_factors(p - 1))  # sorted(): determinism rule
    for q in factors:
        if pow(g, (p - 1) // q, p) == 1:
            return False
    return True


