    # Ensure n is a multiple of 4 to maintain the invariant n % 4 == 0
    m = rng.randint(2, 14)          # free parameter; widen freely
    n = 4 * m                       # n in {8, 12, ..., 56}
    k = rng.randint(1, 5)           # k >= 1 keeps every factor positive

    assert n % 4 == 0 and k >= 1, (
        "invariant violated: n must stay a multiple of 4 and k >= 1"
    )

    max_product = (m + k) ** 4      # = ((n + 4k)/4)^4, exact since n = 4m

    # Independent route: search every positive integer quadruple summing to n.
    # Since 4 | n, the real optimum a = b = c = d = n/4 is a lattice point,
    # so the searched maximum must equal the formula.
    check = max(
        (a + k) * (b + k) * (c + k) * (n - a - b - c + k)
        for a in range(1, n - 2)
        for b in range(1, n - a - 1)
        for c in range(1, n - a - b)
    )
    assert max_product == check, f"max_product={max_product} check={check}"

    problem = (
        f"Let a, b, c, d be positive integers with a + b + c + d = {n}. "
        f"What is the maximum value of (a + {k})(b + {k})(c + {k})(d + {k})?"
    )

    return problem, str(max_product)

